package main

import("log";"net/http";"os";"github.com/jiejhong/GooseCab/internal/eventbus";"github.com/jiejhong/GooseCab/internal/gateway";"github.com/jiejhong/GooseCab/internal/p1";"github.com/jiejhong/GooseCab/internal/p2";"github.com/jiejhong/GooseCab/internal/registry";"github.com/jiejhong/GooseCab/internal/store";"github.com/jiejhong/GooseCab/internal/transfer")
func main(){path:=os.Getenv("GOOSECAB_DB");if path==""{path="goosecab.db"};s,err:=store.Open(path);if err!=nil{log.Fatal(err)};defer s.Close();api:=&gateway.API{Registry:registry.New()};svc:=p1.New(s);base:=http.NewServeMux();base.HandleFunc("/healthz",func(w http.ResponseWriter,_ *http.Request){w.WriteHeader(200)});base.Handle("/api/",api.Handler());mux:=(&gateway.P1API{Service:svc}).Handler(base);mux=(&gateway.P2API{Service:p2.New(s,api.Registry)}).Handler(mux);bus:=eventbus.New();mux=(&gateway.TransferAPI{Service:transfer.New(s,bus)}).Handler(mux);mux=gateway.Observer(mux);h:=(&gateway.WS{Store:s,Bus:bus}).Handler(mux);log.Println("GooseCab gateway listening on :8080");log.Fatal(http.ListenAndServe(":8080",h))}
